import { Entity } from 'prismarine-entity'
import { IndexedData, Entity as EntityData } from 'minecraft-data'
import { snakeCase } from 'change-case'
import entitiesStaticData from './entityData.json'
import { debug } from './debug'

// entityData.json is generated by scripts/entities/genEntityData.js from vanilla's Entity.isPickable overrides for every
// version from 1.8.9 to 26.3: "attackable" are the entities the crosshair can pick (vanilla attacks or uses whatever it
// picks), "conditional" the ones whose pickability depends on their state.

const entityRenames = entitiesStaticData.entityRenames as Record<string, string | false>
const allEntityNames = Object.fromEntries([...entitiesStaticData.attackable, ...entitiesStaticData.notAttackable].map(x => [x, true]))
const attackableEntityNames = new Set(entitiesStaticData.attackable)

/** the entity's name as entityData.json knows it (the latest vanilla name), or null for a name that is not an entity */
export const getLatestEntityName = (name: string): string | null => {
  const rename = entityRenames[name] ?? entityRenames[snakeCase(name)]
  if (rename === false) return null // an abstract registration (1.8 - 1.10 "Mob", "Monster")
  let latestEntityName = rename || name
  if (!allEntityNames[latestEntityName]) {
    latestEntityName = snakeCase(latestEntityName)
    if (!allEntityNames[latestEntityName]) return null
  }
  return latestEntityName
}

export const isEntityAttackable = (data: IndexedData, entity: Entity, playerGameMode?: (entity: Entity) => string | undefined) => {
  if (!entity.name) throw new Error('Entity has no name')
  const latestEntityName = getLatestEntityName(entity.name)
  if (!latestEntityName) {
    debug(`Cannot find entity ${entity.name} in entityData.json`)
    return false
  }

  const hardcodedCheck = hardcodedChecks[latestEntityName]
  if (hardcodedCheck) return hardcodedCheck(entity, data.entitiesByName[entity.name], playerGameMode)
  return attackableEntityNames.has(latestEntityName)
}

const hardcodedChecks: Record<string, (entity: Entity, entityData: EntityData | undefined, playerGameMode?: (entity: Entity) => string | undefined) => boolean> = {
  armor_stand: (entity, entityData) => isArmorStandAttackable(entity, entityData!),
  // Player.isPickable / EntitySelector.NO_SPECTATORS: a spectator is never picked
  player: (entity, _, playerGameMode) => playerGameMode?.(entity) !== 'spectator'
}

export function isArmorStandAttackable(entity: Entity, entityData: EntityData) {
  const clientFlags = Number(entity.metadata?.[entityData?.metadataKeys?.indexOf('client_flags') ?? 14] ?? 0)
  const isMarker = (clientFlags & 16) !== 0
  return !isMarker
}
